import{_ as a,o as r,c as d,a2 as e}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"সহজীবী সভ্যতার সংবিধান","description":"","frontmatter":{},"headers":[],"relativePath":"bn/03-共生文明宪章.md","filePath":"bn/03-共生文明宪章.md"}'),o={name:"bn/03-共生文明宪章.md"};function l(i,t,n,s,h,_){return r(),d("div",null,[...t[0]||(t[0]=[e('<h1 id="সহজীবী-সভ্যতার-সংবিধান" tabindex="-1">সহজীবী সভ্যতার সংবিধান <a class="header-anchor" href="#সহজীবী-সভ্যতার-সংবিধান" aria-label="Permalink to &quot;সহজীবী সভ্যতার সংবিধান&quot;">​</a></h1><table tabindex="0"><thead><tr><th>প্রকল্প</th><th>বিষয়বস্তু</th></tr></thead><tbody><tr><td>নথি নম্বর</td><td>03</td></tr><tr><td>মডিউল</td><td>মূল নীতি ও কোর সেটিং</td></tr><tr><td>মূল কীওয়ার্ড</td><td>সংবিধান, মৌলিক আইন, সহজীবী ব্যবস্থা, হাজারো জাতির প্রজাতন্ত্র, অধিকার ও কর্তব্য</td></tr></tbody></table><h2 id="_1-সংবিধানের-মর্যাদা-ও-প্রকৃতি" tabindex="-1">1. সংবিধানের মর্যাদা ও প্রকৃতি <a class="header-anchor" href="#_1-সংবিধানের-মর্যাদা-ও-প্রকৃতি" aria-label="Permalink to &quot;1. সংবিধানের মর্যাদা ও প্রকৃতি&quot;">​</a></h2><p>সহজীবী সভ্যতার সংবিধান হলো দশ হাজার আত্মা ও ভারসাম্যপূর্ণ নোঙরের মূল মহাবিশ্বে নোঙর সহজীবী সভ্যতার মৌলিক আইন, এবং সমস্ত আইন, ব্যবস্থা ও নীতির সর্বোচ্চ ভিত্তি। সংবিধান &quot;নোঙর সহজীবী সভ্যতার ঘোষণা&quot; কে মানসিক অগ্রদূত হিসেবে গ্রহণ করে, এবং ঘোষণার মূল দাবিগুলোকে বাধ্যতামূলক আইনি বিধানে রূপান্তরিত করে। সংবিধানের প্রভাব হেং ইয়ানঝোউতে সহজীবী সভ্যতায় যোগদানকারী সমস্ত জাতি, বিমান ও ব্যক্তিকে কভার করে, এবং সংবিধানের সাথে সাংঘর্ষিক কোনো স্থানীয় আইন, ধর্মসংঘের নিয়ম বা জাতিগত অভ্যাস অবৈধ।</p><p>সংবিধানের প্রকৃতি তিনটি বিষয়ে সংক্ষেপে বলা যায়: প্রথমত, এটি একটি সভ্যতার চুক্তি, যা হাজারো জাতির মধ্যে সহজীবী বিবর্তন সম্পর্কে মৌলিক ঐকমত্য; দ্বিতীয়ত, এটি একটি অধিকার-সুরক্ষা গ্রন্থ, যা প্রতিটি জীবের সহজীবী সভ্যতায় মৌলিক অধিকার ও স্বাধীনতা স্পষ্টভাবে নির্ধারণ করে; এবং তৃতীয়ত, এটি একটি ক্ষমতা-সীমাবদ্ধকরণ আইন, যা সভ্যতার পরিচালনা প্রতিষ্ঠানের ক্ষমতার জন্য অতিক্রমযোগ্য সীমা নির্ধারণ করে।</p><h2 id="_2-সংবিধানের-মৌলিক-নীতি" tabindex="-1">2. সংবিধানের মৌলিক নীতি <a class="header-anchor" href="#_2-সংবিধানের-মৌলিক-নীতি" aria-label="Permalink to &quot;2. সংবিধানের মৌলিক নীতি&quot;">​</a></h2><p>সংবিধান নিম্নলিখিত ছয়টি মৌলিক নীতি স্থাপন করে, যা সমস্ত বিধানে প্রবাহিত:</p><ol><li><strong>সহজীবন সর্বোচ্চ নীতি</strong>: যেকোনো ব্যবস্থা নকশা ও ক্ষমতা প্রয়োগের সর্বোচ্চ লক্ষ্য হলো হাজারো জাতির সহজীবী বিবর্তনকে উৎসাহিত করা। যখন ব্যক্তিগত স্বার্থ ও সমষ্টিগত সহজীবী স্বার্থের সংঘর্ষ ঘটে, তখন সহজীবী স্বার্থকে অগ্রাধিকার দেওয়া হয়, কিন্তু ব্যক্তিকে অবশ্যই যুক্তিসঙ্গত ক্ষতিপূরণ ও বিকল্প পথ প্রদান করতে হবে।</li><li><strong>লুণ্ঠন-বিরোধী নীতি</strong>: সংবিধান সব রকমের লুণ্ঠন আচরণ নিষিদ্ধ করে, যার মধ্যে শক্তি লুণ্ঠন, মূল উৎস গ্রাস, মানসিক দাসত্ব, সম্পদ একচেটিয়াকরণ অন্তর্ভুক্ত কিন্তু সীমাবদ্ধ নয়। লুণ্ঠনকে কেন্দ্র করে যেকোনো সাধনা পদ্ধতি অবৈধ ঘোষিত হয়।</li><li><strong>বিবর্তন অধিকারের সমানতা নীতি</strong>: সমস্ত জীব বিবর্তন অধিকারের সামনে সমান, জাতি, রূপ, বংশগত বা প্রাথমিক সাধনা-স্তরের পার্থক্যের কারণে বিভক্ত হয় না। রাষ্ট্র ও সভ্যতার দুর্বল গোষ্ঠীদের জন্য অতিরিক্ত বিবর্তন সহায়তা প্রদানের বাধ্যবাধকতা রয়েছে।</li><li><strong>বেশি পরিশ্রম, বেশি পুরস্কার নীতি</strong>: বিবর্তন সম্পদের বণ্টনের প্রধান ভিত্তি হলো ব্যক্তির সহজীবী জালে অবদান; অবদান যত বেশি, প্রাপ্ত সম্পদ ও সহায়তা তত বেশি। একই সাথে মৌলিক নিরাপত্তা লাইন স্থাপন করা হয়েছে, যা নিশ্চিত করে যে কম অবদানকারী ব্যক্তিরাও মৌলিক বিবর্তন শর্ত পেতে পারে।</li><li><strong>স্বায়ত্তশাসন ও সহ-শাসনের সমন্বয় নীতি</strong>: প্রতিটি জাতি সংবিধান লঙ্ঘন না করে অভ্যন্তরীণ বিষয়ে স্বায়ত্তশাসনের অধিকার ভোগ করে; জাতি-ব্যাপী ও বিমান-ব্যাপী পাবলিক বিষয় হাজারো জাতির প্রজাতন্ত্র প্রতিষ্ঠান দ্বারা সহ-শাসিত হয়।</li><li><strong>বাস্তবতাকে ভিত্তি হিসেবে নীতি</strong>: সংবিধানের সব ব্যবস্থা নকশার একমাত্র বাস্তব ভিত্তি হলো বাস্তব জগৎ; কোনো কাল্পনিক জগতের অধিকার-কর্তব্য সম্পর্ক বাস্তবতার উপরে আরোপ করা যাবে না বলে স্বীকার করা হয় না।</li></ol><h2 id="_3-সংবিধানের-মৌলিক-কাঠামো" tabindex="-1">3. সংবিধানের মৌলিক কাঠামো <a class="header-anchor" href="#_3-সংবিধানের-মৌলিক-কাঠামো" aria-label="Permalink to &quot;3. সংবিধানের মৌলিক কাঠামো&quot;">​</a></h2><p>সংবিধান ভূমিকা, মূল নীতি, মৌলিক অধিকার ও কর্তব্য, সভ্যতা প্রতিষ্ঠান, আইনি ব্যবস্থা এবং সংশোধন প্রক্রিয়া ছয়টি অংশ নিয়ে গঠিত:</p><table tabindex="0"><thead><tr><th>অংশ</th><th>মূল বিষয়বস্তু</th><th>ধারার সংখ্যা</th></tr></thead><tbody><tr><td>ভূমিকা</td><td>সংবিধানের ঐতিহাসিক পটভূমি, মানসিক উৎস ও চূড়ান্ত লক্ষ্য ব্যাখ্যা</td><td>অসংখ্যক</td></tr><tr><td>মূল নীতি</td><td>সভ্যতার প্রকৃতি, মহাবিশ্ব-দর্শন, মূল ব্যবস্থা ও মৌলিক নীতি নির্ধারণ</td><td>30 ধারা</td></tr><tr><td>মৌলিক অধিকার ও কর্তব্য</td><td>জীবের বিবর্তন অধিকার, তথ্য অধিকার, অংশগ্রহণ অধিকার ইত্যাদি মৌলিক অধিকার ও সংশ্লিষ্ট কর্তব্য নির্ধারণ</td><td>50 ধারা</td></tr><tr><td>সভ্যতা প্রতিষ্ঠান</td><td>হাজারো জাতির প্রজাতন্ত্র পরিষদ, সহজীবী কার্যকরী কমিটি, নোঙর আদালত ইত্যাদি প্রতিষ্ঠানের গঠন ও ক্ষমতা নির্ধারণ</td><td>40 ধারা</td></tr><tr><td>আইনি ব্যবস্থা</td><td>সংবিধানের নিচে শ্রম আইন, ভোক্তা সুরক্ষা আইন ও পাঁচটি সহায়ক আইনের আইনপ্রণয়ন ক্ষমতা ও প্রয়োগ নিয়ম নির্ধারণ</td><td>20 ধারা</td></tr><tr><td>সংশোধন প্রক্রিয়া</td><td>সংবিধানের সংশোধন প্রস্তাব, বিচার, ভোট, কার্যকরীকরণ প্রক্রিয়া নির্ধারণ</td><td>10 ধারা</td></tr></tbody></table><h2 id="_4-মৌলিক-অধিকার-ও-কর্তব্য" tabindex="-1">4. মৌলিক অধিকার ও কর্তব্য <a class="header-anchor" href="#_4-মৌলিক-অধিকার-ও-কর্তব্য" aria-label="Permalink to &quot;4. মৌলিক অধিকার ও কর্তব্য&quot;">​</a></h2><p>সংবিধান দ্বারা নির্ধারিত মূল মৌলিক অধিকার অন্তর্ভুক্ত:</p><ul><li><strong>বিবর্তনের পছন্দের অধিকার</strong>: প্রতিটি জীব স্বাধীনভাবে সাধনা পদ্ধতি ও বিবর্তনের পথ বেছে নিতে পারে, কেউ জোরপূর্বক করতে পারবে না</li><li><strong>পদ্ধতি অর্জনের অধিকার</strong>: প্রতিটি জীব তিনশটি মূল সাধনা পদ্ধতির মৌলিক উপায় বিনামূল্যে অর্জন করতে পারে</li><li><strong>সম্পদ বণ্টনের অধিকার</strong>: প্রতিটি জীব উৎপাদন-সংযুক্ত চুক্তি ব্যবস্থার মাধ্যমে মৌলিক সাধনা সম্পদ অর্জন করতে পারে</li><li><strong>নোঙর বিন্দু সংযোগের অধিকার</strong>: নির্দিষ্ট স্তরে পৌঁছানো প্রতিটি জীব সংশ্লিষ্ট স্তরের নোঙর বিন্দু জালে সংযুক্ত হতে পারে</li><li><strong>তথ্য ও অংশগ্রহণের অধিকার</strong>: প্রতিটি জীব সভ্যতার পাবলিক বিষয় সম্পর্কে জানতে এবং সিদ্ধান্তে অংশ নিতে পারে</li><li><strong>প্রতিকার ও আবেদনের অধিকার</strong>: প্রতিটি জীব অধিকার লঙ্ঘিত হলে নোঙর আদালতে আবেদন করতে পারে</li></ul><p>সংশ্লিষ্ট মূল কর্তব্য অন্তর্ভুক্ত: লুণ্ঠন-বিরোধী নীতি মেনে চলা, নোঙর বিন্দু জালের স্থিতিশীলতা বজায় রাখা, সহজীবী প্রতিক্রিয়া চক্রে অংশ নেওয়া, সাধনা জ্ঞান বংশগতভাবে প্রেরণ করা, মহাবিশ্বের পরিবেশ-বাস্তুতন্ত্র রক্ষা করা।</p><h2 id="_5-সংবিধানের-সংশোধন-ও-নিশ্চয়তা" tabindex="-1">5. সংবিধানের সংশোধন ও নিশ্চয়তা <a class="header-anchor" href="#_5-সংবিধানের-সংশোধন-ও-নিশ্চয়তা" aria-label="Permalink to &quot;5. সংবিধানের সংশোধন ও নিশ্চয়তা&quot;">​</a></h2><p>সংবিধানের সংশোধনের জন্য হাজারো জাতির প্রজাতন্ত্র পরিষদের পঞ্চমাংশেরও বেশি সংসদ সদস্যের যৌথ প্রস্তাব প্রয়োজন, পরিষদের তিন-চতুর্থাংশেরও বেশি সংখ্যাগরিষ্ঠতা দিয়ে পাস হতে হবে, এবং মহাবিশ্বের মূল নোঙর বিন্দু দ্বারা যাচাই করে নিশ্চিত করতে হবে যে এটি সহজীবী নিয়ম লঙ্ঘন করছে না — তারপর কার্যকর হবে। সংবিধানের ব্যাখ্যার ক্ষমতা নোঙর আদালতের।</p><p>সংবিধানের বাস্তবায়ন নিশ্চিত করতে, সহজীবী সভ্যতা একটি সাংবিধানিক পর্যালোচনা ব্যবস্থা প্রতিষ্ঠা করেছে: কোনো আইন, বিধান বা নীতি কার্যকর হওয়ার আগে নোঙর আদালতের সাংবিধানিকতা পর্যালোচনা দিতে হবে; কোনো জীব যদি মনে করে পাবলিক ক্ষমতার আচরণ অসাংবিধানিক, তিনি সাংবিধানিক মামলা দায়ের করতে পারেন।</p><h2 id="উপসংহার" tabindex="-1">উপসংহার <a class="header-anchor" href="#উপসংহার" aria-label="Permalink to &quot;উপসংহার&quot;">​</a></h2><p>সহজীবী সভ্যতার সংবিধান হলো নোঙর সহজীবী সভ্যতার প্রাতিষ্ঠানিক ভিত্তি। এটি &quot;লুণ্ঠন-বিরোধ, সহজীবন-সমর্থন&quot; এর দর্শনকে কার্যকরী, প্রতিকারযোগ্য ও তদারকিযোগ্য আইনি বিধানে রূপান্তরিত করে, এবং হাজারো জাতির সম্মিলিত অগ্রগতির জন্য শক্তিশালী প্রাতিষ্ঠানিক নিশ্চয়তা প্রদান করে। সংবিধান কোনো অপরিবর্তনীয় মতবাদ নয়, বরং সভ্যতার বিবর্তনের সাথে ক্রমাগত উন্নত হওয়া একটি জীবন্ত মৌলিক আইন।</p><h2 id="সম্পর্কিত-নথি" tabindex="-1">সম্পর্কিত নথি <a class="header-anchor" href="#সম্পর্কিত-নথি" aria-label="Permalink to &quot;সম্পর্কিত নথি&quot;">​</a></h2><ul><li>01-锚点共生文明宣言 (নোঙর সহজীবী সভ্যতার ঘোষণা)</li><li>40-共生宪法总纲 (সহজীবী সংবিধানের মূল নীতি)</li><li>49-治理框架与权力制衡 (পরিচালনা কাঠামো ও ক্ষমতার ভারসাম্য)</li></ul>',22)])])}const p=a(o,[["render",l]]);export{c as __pageData,p as default};
